insert into public.catalog_archives (kind,checked_on,original_items,legacy_due,legacy_timeline,kind_labels)
select kind,checked_on,original_items,legacy_due,legacy_timeline,kind_labels from jsonb_populate_recordset(null::public.catalog_archives,'[{"kind":"rec","checked_on":"2026-09-13","original_items":[{"name":"华为","en":"Huawei","status":"open","rec":"likely","src":"mix","opened":"官网亲见：华为2027届应届生招聘启动，落款 2026-08-15。顶尖 AI 专项稿 2026-05-19；实习生启动 2026-03-15。","closes":"未见统一网申截止。新闻只写 8/15 启动。职位池要点登录，按岗招满即止的可能性大。","window":"国内本硕：2027-01-01 至 2027-12-31；国内博士与海外本硕博：2026-01-01 至 2027-12-31。","city":"深圳 / 北京 / 上海 / 东莞 / 杭州 / 南京 / 西安 / 武汉 / 成都 / 苏州","jobs":"首页按「应届生职位 / 实习生 / AI 专项」招，少见「推荐算法」四字。Playwriter 点「查看职位」未进列表（疑似要登录），所以没有岗位名级证据。负一屏、应用市场、资讯可能有搜推。","req":"流程：投递 → 上机/测评 → 面试 → 录用 → 签约。官网提醒勿信付费「内推实习」。","links":[["华为校园招聘","https://career.huawei.com/cn/campus-recruitment"]],"note":"部分亲见。推荐履历可投 AI 应用/算法，但别按信息流厂准备。"},{"name":"拼多多","en":"PDD","status":"open","rec":"yes","src":"see","rev":"2026-08-20","opened":"官网亲见两条 2027 技术专场：大模型算法工程师 2026-05-08（标紧缺）；算法工程师 2026-07-05。搜岗位名「推荐」= 0。8/20 职位页可见「常规批次」页签。","closes":"提前批官网 FAQ 仍是 2026-07-06 至 2026-08-23。8/20 未见正式批启动公告与新截止日期。提前批结果不影响正式批。不要为了等正式批空过 8/23。","window":"算法工程师：2027 届，硕士及以上。大模型岗：2026.9–2027.8 获硕/博学位。","city":"上海","jobs":"算法工程师 JD 原文：用机器学习/深度学习/图计算优化 App 内外搜索、推荐、广告等。大模型岗 JD 写「AI 交互式搜索、生成式推荐、智能导购」。咨询 pddcampus@pddglobalhr.com。","req":"算法岗：硕士+，Linux，TF/PyTorch/Hive 加分，搜推/广告经验优先。大模型岗：扎实 ML、熟悉 GPT/DeepSeek/多模态，顶会或竞赛加分。","links":[["PDD 校园招聘","https://careers.pddglobalhr.com/campus/grad"],["算法工程师 JD","https://careers.pddglobalhr.com/campus/grad/detail?positionId=793e8792-b686-4950-b348-281f8274c5de"]],"note":"官网亲见。标题不叫推荐，JD 叫。8/23 前先投技术专场，不要等正式批。"},{"name":"滴滴","en":"DiDi","status":"open","rec":"yes","src":"see","opened":"官网首页大字「滴滴27届秋招正式启动」。两岗均发布于 2026-08-13。","closes":"常规秋招：招满即关；牛客日程标到 2026-10-13。未来精英：2026-07-23 至 2026-09-23。全渠道 3 次主动投递。","window":"2027 届。起终点推荐：本科及以上。国际化外卖-推荐：硕士及以上。","city":"起终点：北京。外卖推荐：北京 / 上海。","jobs":"① 27届秋招-算法工程师-起终点推荐（CTO）：上下车点召回/精排、多模态 POI、目的地检索 Agent。② 27届秋招-AI算法工程师（国际化外卖-推荐）：生成式召回、个性化排序、AI 创意分发。","req":"2027届-秋招允许投递 3 次。英语流利对外卖岗加分。咨询 campus@didiglobal.com。","links":[["滴滴校招搜推荐","https://campus.didiglobal.com/campus_apply/didiglobal/96064#/jobs?keyword=%E6%8E%A8%E8%8D%90"]],"note":"官网亲见，而且是真正的推荐岗，不是只写算法。"},{"name":"小米","en":"Xiaomi","status":"open","rec":"yes","src":"see","opened":"官网亲见 2027 届全球校园招聘。投递须知：网申 2026-08-10 至 2027-06 底。飞书职位池搜「推荐」13 条。","closes":"官网须知写到 2027-06 底。快科技/超级简历写 2026-12-31。两套口径都在，先按须知，12/31 前务必投完。","window":"2026-09-01 至 2027-08-31 毕业。","city":"搜推岗：北京 / 南京。另有上海 / 武汉 / 西安 / 深圳 / 新加坡。","jobs":"搜索与推荐算法工程师（正式，2027）：整套搜推架构、大模型搜推、AI 搜索优先。另有广告算法（召回/CTR）、算法架构-训练框架（广告/搜索/推荐，生成式推荐）。","req":"最多投 2 个职位，同时仅 1 个流程，默认先处理最早投的；投后不可改岗。面试至少两轮。留用实习生不建议再投。","links":[["小米校招首页","https://hr.xiaomi.com/website/campus.html"],["2027 职位池","https://xiaomi.jobs.f.mioffice.cn/campus/?spread=J7NS6YR"],["投递须知","https://hr.xiaomi.com/website/campus-notice.html#id=13"]],"note":"官网亲见。收藏实习生页的话，改走校园招聘正式通道。"},{"name":"哔哩哔哩","en":"Bilibili","status":"open","rec":"yes","src":"see","opened":"jobs.bilibili.com 亲见「2027届秋季校园招聘正式启动」。三推荐岗均 2026-08-07 发布。","closes":"牛客/超级简历：网申 2026-08-03 至 2026-10-03。官网 FAQ 没写死截日，按 10/03 倒计时。","window":"2026-09-01 至 2027-08-31。大陆看毕业证，海外看学位证。","city":"三岗都是上海。","jobs":"推荐算法工程师【2027届】；电商推荐算法工程师【2027届】；推荐研发工程师【2027届】。应届池共 97 岗，搜「推荐」剩 3。","req":"最多 2 志愿，按投递顺序认一二志愿，优先一志愿。仅初筛可撤回/改志愿/改简历。进度看官网投递记录或「哔哩哔哩招聘」公众号。","links":[["B 站应届搜推荐","https://jobs.bilibili.com/campus/positions?name=%E6%8E%A8%E8%8D%90&type=3"],["校招首页","https://jobs.bilibili.com/campus"]],"note":"官网亲见。主站 Feed 和电商推荐不是同一条故事。"},{"name":"美团","en":"Meituan","status":"open","rec":"yes","src":"see","rev":"2026-08-20","opened":"8/17 晚间正式启动 2027。官网搜「推荐」8/20 为 39（8/17 快照 36）。应届【北斗】推荐大模型算法工程师仍在；新增大模型搜索推荐算法工程师（北/上，更新 2026-08-17）。","closes":"北斗专项牛客曾标 06-03 至 07-03（窗口或已过，岗还在）。正式批未见官方统一截止，按岗招满即下。南京本地宝 10/31 不当官网死线。","window":"FAQ：毕业 2026-11 至 2027-10。北斗应届走官网应届通道；大量转正实习 / 日常实习并行。","city":"应届北斗：北京。大模型搜索推荐：北京 / 上海。部分实习含上海。","jobs":"应届：【北斗】推荐大模型算法工程师（日均数十亿请求，MTGR，生成式 Agentic 推荐）；大模型搜索推荐算法工程师（8/17 新）。实习/转正实习：生成式推荐系统、推荐大模型、全球 Agentic 推荐