select id,kind,position,event_on,title,summary,items from jsonb_populate_recordset(null::public.change_logs,'[{"id":"rec-log-0","kind":"rec","position":0,"event_on":"2026-09-13","title":"第六轮：原版布局恢复＋重点信息复核","summary":"保留所有原模块、55条原卡片、40个原时间线节点和三轮旧日志；保留上版新增2个子项目。本轮正文与索引分别标识。","items":[["change","版式与时间线","回到原暖色双栏卡片与原板块顺序。原时间线40条全部保留，新增9条事件和北京时间今天定位，默认完整展示。"],["change","字节跳动","官网FAQ正文重核：2027-05-31投递窗口；12/31年度次数窗口，1/1刷新2次。"],["change","拼多多 / 小红书 / SHEIN","拼多多正式批官网已显示；小红书9/11高校页面已发布；SHEIN本届为官方索引证据，动态JD未重数。"],["add","有道 / 雷火 / 云音乐","保留上一版独立子项目；有道10/11 10:00是笔试，雷火10/16仅自身截止，云音乐为转载搜推广岗位。"],["warn","旧日期与岗位数量","所有旧日期、数量与岗位详情保留；未重核的加历史标签。货拉拉GMT、同花顺博士专项不算硕士推荐算法紧急截止。"],["same","原始细节","保留32家核心、23条原补网及原三轮日志；每张原卡均可展开完整8月记录。"]]},{"id":"rec-log-1","kind":"rec","position":1,"event_on":"2026-08-31","title":"第四轮审计","summary":"动态官网职位池优先。新增可投入口，也把空职位池、旧批次和冲突字段显式降级。","items":[["add","携程","官网 8/26 开放 2027 校招；本轮搜到 11 个算法岗，含 NLP/智能推荐生成、时间序列与强化学习方向。由等待改为已开。"],["add","网易","官网当前列出互联网、互娱、雷火三个 2027 项目；有道 8/31 启动。由实习/入口可见改为正式批已开。"],["add","新浪 / 微博","2027 技术项目当前 8 个全职岗位，含 8/21 发布的广告算法。由等待改为已开；未核到推荐标题，rec 降为 likely。"],["add","度小满","8/18 启动 2027，AI/机器学习方向可投；加入中厂补网。"],["add","Wind 万得","官网有 AI 算法工程师（推荐算法），接受数学/统计；但毕业年份字段疑似未更新，卡片明确提示投前核资格。"],["change","腾讯音乐","官网 2027 FAQ 与 32 个校园岗位已核；每人 1 岗、3 个偏好业务线、招满即止。未用社招推荐岗冒充校招，rec 改为 likely。"],["warn","截止日","页面日期改为运行时当天；删除未核实的网易 10/15 整体截止，历史日期仍保留在日志而不进入倒计时。"],["hold","仍未见 27 秋 RecSys","360 官网仍是 26 春；小红书当前是 2026 春招/专项/实习；爱奇艺、SHEIN、Soul、哈啰等仍未核到 2027 正式推荐岗。"]]},{"id":"rec-log-2","kind":"rec","position":2,"event_on":"2026-08-20","title":"第三轮对照","summary":"相对 8/17 快照。官网 FAQ / JD / 笔试日历优先于超级简历。没有再全量 Playwriter。","items":[["add","荣耀","官网 8/18「2027届校园招聘全球启动」。应届池已开；推荐算法标题未核到，进池搜算法。卡片从实习改为已开。"],["add","唯品会","公开稿 8/17 启动 2027 秋招，搜索算法广州/上海。无「推荐算法」标题。卡片从等待改为已开。"],["add","美团","8/17 晚间正式启动 2027。搜「推荐」36→39。新增大模型搜索推荐算法工程师（北/上）。FAQ：3 次志愿，毕业 2026-11～2027-10。勿用南京本地宝 10/31。"],["add","快手","8/18 新开三岗。搜「推荐」15→16。已开池可补投。"],["change","拼多多","提前批仍 8/23。职位页出现「常规批次」页签，但无正式批公告。不要等正式批。"],["change","字节跳动","官网 FAQ：投递窗至 2027-05-31；4 次机会（12/31 前 2 次，2027-01-01 刷新 2 次）。12/31 从「网申关窗」改为次数窗口。倒计时不再按 12/31。"],["change","饿了么","生成式推荐 OneRec JD 窗 8/05–11/30。推荐含量 likely → yes。"],["warn","得物","倒计时仍按 9/07。官网技术笔试日历排到 11/01（含 10/10、10/24）；聚合另有网申 10/10。9/07 当首轮，不当最后一天。"],["warn","vivo","再核：网申/初筛 9/15 12:00，研发笔试同日 15:00。别拖到当天上午。"],["change","同花顺","官网列表见生成式推荐算法研究员（博士专项）。硕士 RecSys 仍弱。第三方约 9/19。"],["change","科大讯飞","27 秋季约 7/23 已在招，快照按实习低估。卡片改为秋招已开。推荐专项仍弱。"],["change","网易","应届菜单有 2027 入口，首页仍未见 RecSys JD。不当已开推荐岗。"],["change","Soul","飞书招聘现为社招。27 秋招 RecSys 继续等。"],["hold","微博","第三方有 8/18 秋招+广告算法说法，独立核官网未站住。不当新开。"],["hold","小红书","仍未见 27 秋招正式批。继续实习 / Ace / REDstar。"],["same","作业帮 / 货拉拉 / 挚文 / 去哪儿","作业帮 9/07、货拉拉 GMT 9/13、挚文笔试 8/25、去哪儿保守 9/20，均未改。GMT 不是 RecSys。"],["same","大厂岗量","腾讯 / 阿里 / 蚂蚁 / 百度 / 华为 / 京东 / 小米 / 滴滴 / B站 / OPPO / Shopee 相对 8/17 基本没动。"],["hold","仍在等 27 秋 RecSys","携程、360、MetaApp、SHEIN、爱奇艺、哈啰、芒果TV、喜马拉雅、阅文、网易云、Keep、同程、虎牙、BOSS。"]]},{"id":"rec-log-3","kind":"rec","position":3,"event_on":"2026-08-17","title":"第二轮深挖（基线）","summary":"Playwriter 逐家打开校招站、搜「推荐」。建立本表、截止日倒计时和时间线。之后对照都相对这一版。","items":[["add","本表","32 家收藏名单 + 中厂补网。官网亲见 / 部分亲见 / 新闻转载分开标。"],["add","拼多多","提前批 7/6–8/23。算法工程师 JD 写搜索、推荐、广告。"],["add","腾讯 / 字节 / 快手 / 美团 / 阿里 / 蚂蚁 / 百度","搜「推荐」岗名或 JD 抠出。美团当时 36 岗，快手 15 岗。"],["add","得物 / 作业帮 / vivo","得物、作业帮按 9/07；vivo 网申 9/15 12:00。"],["add","京东新锐之星","8/17 开网申，至 11/30。"],["hold","小红书 / 微博 / 携程 / SHEIN","当时即未见 27 秋招正式批。"]]}]'::jsonb)
on conflict (id) do update set kind=excluded.kind,position=excluded.position,event_on=excluded.event_on,title=excluded.title,summary=excluded.summary,items=excluded.items;

